import {STATS,AREAS,CARDS,RELICS,EVENTS,COMBOS,TRAITS,MISSIONS,CITIES} from './data.js';
import {newGame,available,budget,timeBudget,income,forecast,selectCards,move,reroll,resolveYear,chooseEvent,chooseRelic,ending,validateSave} from './engine.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='life-meadow-save-v1',ALBUM='life-meadow-album-v1';let state,tab='board',collection='combos',storageOK=true,album={runs:[],achievements:[]};
try{const raw=localStorage.getItem(KEY);state=raw?validateSave(JSON.parse(raw)):newGame();const a=JSON.parse(localStorage.getItem(ALBUM)||'null');if(a&&Array.isArray(a.runs)&&Array.isArray(a.achievements))album=a;}catch{state=newGame();}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(ALBUM,JSON.stringify(album));}catch{storageOK=false;}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function act(fn){try{state=fn(state);if(state.phase==='end')recordEnd();save();render();}catch(e){toast(e.message);}}
function recordEnd(){const e=ending(state),id=state.seed+'|'+JSON.stringify(state.history.map(h=>[h.cards,h.event]))+'|'+state.relics.join(',');if(!album.runs.some(r=>r.id===id)){album.runs.unshift({id,seed:state.seed,name:state.name,ending:e.name,stats:state.stats,mission:e.mission});album.runs=album.runs.slice(0,30);album.achievements=[...new Set([...album.achievements,...e.achieved])];}}
const effectText=e=>Object.entries(e).map(([k,v])=>`${STATS[k]} ${v>0?'+':''}${v}`).join(' · ');
function top(){return `<header class="topbar"><div class="brand"><div class="brand-mark" aria-hidden="true">❋</div><div><strong>人生原野</strong><small>LIFE MEADOW · 育儿模拟器</small></div></div><div class="top-actions"><span class="chip">V0.1 · 完整试玩</span><button class="button quiet" data-action="save-menu">存档</button><button class="button" data-action="new">新的人生 ＋</button></div></header><nav class="tabs" aria-label="游戏视图">${[['board','成长之旅'],['map','机会社区'],['journal','人生年鉴'],['collection','成长图鉴']].map(([id,t])=>`<button class="tab ${tab===id?'active':''}" data-tab="${id}" aria-current="${tab===id?'page':'false'}">${t}</button>`).join('')}</nav>`;}
function sidebar(){const f=state.phase==='plan'?forecast(state):null;const trait=TRAITS.find(t=>t.id===state.trait),mission=MISSIONS.find(m=>m.id===state.mission);return `<aside class="side"><section class="panel profile"><div class="profile-top"><span class="profile-name">${esc(state.name)}</span><span class="age-number">${state.age}<small> 岁</small></span></div><div class="trait" title="${esc(trait.text)}">✦ ${trait.name}</div><p class="small">${trait.text}</p>${Object.entries(STATS).map(([k,l])=>`<div class="stat"><div class="stat-label"><span>${l}</span><span>${state.stats[k]}${f&&state.plan.length?`<span class="delta">${f.deltas[k]>=0?'+':''}${f.deltas[k]}</span>`:''}</span></div><div class="bar" role="meter" aria-label="${l}" aria-valuenow="${state.stats[k]}" aria-valuemin="0" aria-valuemax="100"><i style="width:${state.stats[k]}%"></i></div></div>`).join('')}<div class="stress"><div class="stat-label"><span>身心负荷</span><span class="${state.load>55?'bad':''}">${state.load} / 100</span></div><div class="bar"><i style="width:${state.load}%;background:${state.load>55?'#dd9d83':'#83ab97'}"></i></div><p>${state.load>55?'需要多一点恢复和支持。':'还有呼吸和恢复的空间。'}</p></div><p class="small" style="margin-top:15px">${state.mode==='gentle'?'舒缓':'标准'}模式 · 数值为游戏刻度</p></section><section class="panel"><div class="eyebrow">这一局的初心</div><div class="mission-title">${mission.name}</div><p class="small">${mission.text}</p></section><section class="panel"><div class="eyebrow">一路积累的信物 · ${state.relics.length}/5</div><div class="relic-list">${state.relics.length?state.relics.map(id=>{const r=RELICS.find(x=>x.id===id);return `<div class="relic-item" title="${esc(r.text)}"><span class="relic-icon">${r.icon}</span><span>${r.name}</span></div>`;}).join(''):'<p class="small">每走过3年，选择一件永久改变本局规则的信物。</p>'}</div></section></aside>`;}
function timeline(){return `<div class="timeline" aria-label="成长进度">${[0,3,6,9,12,15,18].map((v,i)=>`<div class="timepoint ${state.age>=v?'done':''} ${Math.floor(state.age/3)===i?'current':''}"><b>${v}</b><span>${['初见','幼年','入学','探索','青春','远行','成年'][i]}</span></div>`).join('')}</div>`;}
function world(){const area=AREAS.find(a=>a.id===state.area);return `<div class="world"><img src="neighborhood.webp" alt="背着黄色书包的孩子和家人走过绿树环绕的社区" width="1536" height="1024"><div class="world-copy"><div class="eyebrow">CHAPTER ${String(Math.min(6,Math.floor(state.age/3)+1)).padStart(2,'0')} / 06</div><h1>${state.age<3?'每一个小小开始':state.age<6?'世界开始变大':state.age<9?'带着问号长大':state.age<12?'发现自己的光':state.age<15?'练习成为自己':state.age<18?'把选择交还给你':'下一程，由你出发'}</h1><p>${state.age<18?'一年一年，种下更多可能。':'十八年，不过是故事的序章。'}</p><p class="location">⌂ ${state.city} · ${area.name}<br><span class="small">虚构社区剧本</span></p></div></div>`;}
function cardHTML(c){const yes=state.plan.includes(c.id);return `<button class="card ${yes?'selected':''}" data-card="${c.id}" aria-pressed="${yes}" title="${esc(c.text)}"><span class="card-tag"><span>${c.tag}</span><span>${c.load>0?'↗':'↘'} ${Math.abs(c.load)}</span></span><span class="card-symbol" aria-hidden="true">${c.icon}</span><strong>${c.name}</strong><span class="card-effect">${Object.entries(c.effect).map(([k,v])=>`${STATS[k]} +${v}`).join('<br>')}</span><span class="card-cost"><span>◷ ${c.time} 时间</span><span>◈ ${c.cost>=0?c.cost:'赚'+(-c.cost)}</span></span></button>`;}
function planView(){const b=budget(state),f=forecast(state),valid=state.plan.length>0&&b.time<=timeBudget(state)&&b.cost<=b.available;return `<div class="section-head"><div><h2>${state.age}—${state.age+1}岁，这一年怎么过？</h2><p>从5张牌里选1—3张。不同类型相遇，会发生新故事。</p></div><button class="button" data-action="reroll" ${state.rerolls||state.cash<1?'disabled':''}>换一手牌 · ◈ 1</button></div>${state.age===0&&!state.history.length?'<div class="hint">先点选成长牌，再点击“走过这一年”。右侧会预览成长变化；每年还有一件意外和一次选择。</div>':''}<div class="hand" aria-label="本年成长手牌">${available(state).map(cardHTML).join('')}</div><div class="combo-box"><div class="combo-label">✦ 组合回响 ${f.combos.length?'· '+f.combos.length+' 组已点亮':''}</div>${f.combos.length?f.combos.map(id=>{const c=COMBOS.find(c=>c.id===id);return `<div class="combo-row lit">${c.text} → ${c.name} · ${effectText(c.bonus)}</div>`;}).join(''):'<div class="combo-row">试试“探索＋联结”或“自然＋恢复”，让日常彼此成全。</div>'}<div class="combo-row">本年负荷预估：${state.load} → ${state.load+f.load} <span class="small">· 事件发生前</span></div></div><div class="commit-row"><div class="budget"><div>◷ 时间 <strong class="${b.time>timeBudget(state)?'bad':''}">${b.time} / ${timeBudget(state)}</strong>　·　已选 <strong>${state.plan.length} / 3</strong></div><div>◈ 结余 <strong class="${b.cost>b.available?'bad':''}">${b.available-b.cost}</strong> = 储蓄${state.cash} + 收入${b.income} − 房租${b.rent} − 活动${b.cost}</div></div><button class="button primary" data-action="resolve" ${!valid?'disabled':''}>走过这一年 →</button></div><p class="small">卡面为基础收益；右侧预览已计入气质、社区、组合、信物和收益递减。</p>`;}
function lastStrip(){return state.last?`<div class="result-strip">${Object.entries(state.last.deltas).filter(([,v])=>v!==0).map(([k,v])=>`<span class="result-pill">${STATS[k]} ${v>0?'+':''}${v}</span>`).join('')}</div>`:'';}
function eventView(){const e=EVENTS.find(e=>e.id===state.eventId);return `<div class="section-head"><div><h2>计划之外，也是生活</h2><p>活动已经结算。现在，回应这一年的小插曲。</p></div></div>${lastStrip()}<article class="event-card"><div class="eyebrow">LIFE HAPPENS · ${state.age}岁</div><h2>${e.title}</h2><p>${e.story}</p><div class="choices">${e.choices.map((c,i)=>`<button class="choice" data-event="${i}" ${state.cash<c.cost?'disabled':''}><strong>${c.label}</strong><span>${effectText(c.effect)}<br>负荷 ${c.load>0?'+':''}${c.load} · ◈ ${c.cost}${state.cash<c.cost?' · 资金不足':''}</span></button>`).join('')}</div></article>`;}
function draftView(){return `<div class="section-head"><div><div class="eyebrow">A LITTLE KEEPSAKE</div><h2>${state.age}岁，留住一件成长信物</h2><p>三选一，持续影响这一局余下的人生。</p></div></div><div class="draft-grid">${state.draft.map(id=>{const r=RELICS.find(r=>r.id===id);return `<button class="relic-card" data-relic="${id}"><span class="card-symbol">${r.icon}</span><strong>${r.name}</strong><p>${r.text}</p></button>`;}).join('')}</div><div class="hint">信物会与活动、社区叠加。试着围绕已有组合，发展属于这个家庭的节奏。</div>`;}
function endView(){const e=ending(state);return `<section class="ending"><div class="eyebrow">十八年的回信</div><h2>${e.name}</h2><p>${esc(state.name)}：${e.text}</p><p class="ending-score">本局初心：<b>${e.mission?'已经达成':'还有另一种可能'}</b> · 发现 ${state.combos.length} 种组合 · 收集 ${state.relics.length} 件信物</p><div class="result-strip">${e.achieved.map(t=>`<span class="result-pill">✧ ${t}</span>`).join('')}</div><div class="modal-actions"><button class="button primary" data-tab="journal">翻开人生年鉴</button><button class="button" data-action="replay">相同起点，再试一种选择</button><button class="button" data-action="share">复制这段人生</button></div><p class="small">一局已经完整结束。存档会保留，随时回来继续探索。</p></section>`;}
function board(){return world()+timeline()+(state.phase==='plan'?planView():state.phase==='event'?eventView():state.phase==='draft'?draftView():endView());}
function mapView(){return `<div class="section-head"><div><div class="eyebrow">OPPORTUNITY NEIGHBORHOODS</div><h2>${state.city} · 选择生活的土壤</h2><p>社区有长处，也有代价。搬家花费3资金，每年最多一次。</p></div></div><div class="hint">以下为虚构社区和0—100游戏指数，六座城市共用平衡参数。居民收入、住房拥有率和教育指数只提供背景，不直接决定孩子的成长。</div><div class="area-grid">${AREAS.map(a=>`<article class="area-card ${state.area===a.id?'current':''}"><div class="area-heading"><div><h3>${a.name}</h3><div class="small">${a.type}${state.area===a.id?' · 现在的家':''}</div></div><span class="area-icon">${a.icon}</span></div><p class="small">${a.desc}</p><div class="area-metrics">${[['教育指数',a.education],['收入指数',a.income],['住房拥有指数',a.ownership],['绿地指数',a.green],['邻里支持',a.support],['服务可达性',a.care]].map(([k,v])=>`<div>${k}<b>${v}</b></div>`).join('')}</div><div class="small">每年房租 ◈ ${a.rent} · 通勤占用 ◷ ${a.commute}<br>每年基础加成：${effectText(a.bonus)}</div><button class="button ${state.area===a.id?'':'primary'}" data-move="${a.id}" ${state.phase!=='plan'||state.area===a.id||state.moved||state.cash<3?'disabled':''}>${state.area===a.id?'住在这里':state.moved?'本年已经搬过家':'搬到这里 · ◈ 3'}</button></article>`).join('')}</div><p class="small">早搬与晚搬会产生不同的累计环境收益，但这些差异是游戏规则，不能作为真实购房或教育建议。</p>`;}
const colors=['#ecc56b','#9acaad','#d8a78e','#adbfea','#d0b6df'];
function chart(){if(!state.history.length)return '';const records=[newGame({seed:state.seed}).stats,...state.history.map(h=>h.after)];return `<svg class="chart" viewBox="0 0 700 230" role="img" aria-label="成长属性随年龄变化的折线图"><g stroke="#365448" stroke-width="1">${[0,25,50,75,100].map(v=>`<line x1="42" y1="${198-v*1.6}" x2="675" y2="${198-v*1.6}"/><text x="8" y="${203-v*1.6}" fill="#b6c7b8" stroke="none" font-size="12">${v}</text>`).join('')}</g>${Object.keys(STATS).map((k,i)=>`<polyline points="${records.map((r,j)=>`${42+j*633/18},${198-r[k]*1.6}`).join(' ')}" fill="none" stroke="${colors[i]}" stroke-width="2.5"/>`).join('')}<text x="42" y="221" fill="#b6c7b8" font-size="12">0岁</text><text x="650" y="221" fill="#b6c7b8" font-size="12">18岁</text></svg><div class="legend">${Object.values(STATS).map((v,i)=>`<span style="color:${colors[i]}">━ ${v}</span>`).join('')}</div>`;}
function journal(){return `<div class="section-head"><div><div class="eyebrow">THE YEARS WE GREW</div><h2>${esc(state.name)}的人生年鉴</h2><p>记下结果，也记下结果是怎样发生的。</p></div><button class="button" data-action="export">导出存档</button></div>${chart()}${state.history.length?`<div style="margin-top:28px">${[...state.history].reverse().map(h=>{const e=EVENTS.find(e=>e.id===h.event.id);return `<article class="log"><h3>${h.age}—${h.age+1}岁 · ${AREAS.find(a=>a.id===h.area).name}</h3><p>${h.cards.map(id=>CARDS.find(c=>c.id===id).name).join(' ＋ ')}</p><p>意外：${e.title} → ${e.choices[h.event.choice].label}</p>${h.notes.map(n=>`<p style="color:var(--gold)">✦ ${esc(n)}</p>`).join('')}<p>${Object.entries(STATS).map(([k,v])=>`${v} ${h.after[k]}`).join(' · ')}</p></article>`;}).join('')}</div>`:'<div class="empty"><div class="card-symbol">≋</div>第一年的回忆，正在等待发生。</div>'}`;}
function collectionView(){return `<div class="section-head"><div><div class="eyebrow">A CABINET OF POSSIBILITIES</div><h2>发现更多成长的方式</h2><p>收集的是故事和策略，不是更优越的孩子。</p></div></div><div class="subnav">${[['combos','组合回响 · 5'],['relics','成长信物 · 12'],['cards','活动卡牌 · 24'],['album','人生收藏 · '+album.runs.length]].map(([id,t])=>`<button class="button ${collection===id?'primary':''}" data-collection="${id}">${t}</button>`).join('')}</div>${collection==='combos'?`<div class="collection-grid">${COMBOS.map(c=>`<article class="collection-item"><div class="card-symbol">${state.combos.includes(c.id)?'✦':'✧'}</div><h3>${c.name}</h3><p>${c.text}</p><p>${effectText(c.bonus)}</p><p>${state.combos.includes(c.id)?'本局已发现':'等待这一局相遇'}</p></article>`).join('')}</div>`:collection==='relics'?`<div class="collection-grid">${RELICS.map(c=>`<article class="collection-item"><div class="card-symbol">${c.icon}</div><h3>${c.name}</h3><p>${c.text}</p><p>${state.relics.includes(c.id)?'本局已拥有':'每3年有机会选择'}</p></article>`).join('')}</div>`:collection==='cards'?`<div class="collection-grid">${CARDS.map(c=>`<article class="collection-item"><div class="card-symbol">${c.icon}</div><h3>${c.name}</h3><p>${c.tag} · ${c.min}—${c.max}岁 · ◷${c.time} · ◈${c.cost}</p><p>${effectText(c.effect)} · 负荷${c.load>0?'+':''}${c.load}</p><p>${c.text}</p></article>`).join('')}</div>`:`${album.achievements.length?`<div class="result-strip">${album.achievements.map(a=>`<span class="result-pill">✧ ${esc(a)}</span>`).join('')}</div>`:''}${album.runs.length?`<div class="collection-grid">${album.runs.map(r=>`<article class="collection-item"><div class="card-symbol">❋</div><h3>${esc(r.name)} · ${esc(r.ending)}</h3><p>种子：${esc(r.seed)}</p><p>${r.mission?'守住初心':'一条不同的路'}</p></article>`).join('')}</div>`:'<div class="empty">完成一局后，结局和成就会留在这里。<br>收藏不会带来数值优势；每个人都能从同样的起点出发。</div>'}`}`;}
function render(){const oldFocus=document.activeElement?.dataset,focusCard=oldFocus?.card;$('#app').innerHTML=`<div class="shell">${top()}<div class="layout"><main class="main" id="main-content">${tab==='board'?board():tab==='map'?mapView():tab==='journal'?journal():collectionView()}</main>${sidebar()}</div><footer class="foot"><span>人生原野 · 独立试玩版　|　${storageOK?'进度自动保存在当前设备':'自动保存不可用，请导出存档'}　|　种子 ${esc(state.seed)}</span><div class="inline"><button data-action="help">玩法与科学边界</button><button data-action="future">完整版计划</button></div></footer></div>`;if(focusCard)$(`[data-card="${focusCard}"]`)?.focus({preventScroll:true});}
function modal(title,content){$('#modal').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="modal-close" data-action="close" aria-label="关闭对话框">×</button></div>${content}`;$('#modal').showModal();}
function newDialog(replay=false){modal(replay?'相同起点，新的选择':'开启一段新的人生',`<p>${state.age>0&&state.phase!=='end'?'开始新局将替换当前自动存档；可以先在“存档”里导出。':'一局18个年份。每年选牌、回应意外，每3年获得一件信物。'}</p><form id="new-form"><label class="field">孩子的名字<input name="child" value="${esc(state.name)}" maxlength="12" required></label><div class="fields"><label class="field">故事发生在<select name="city">${CITIES.map(c=>`<option ${c===state.city?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">节奏<select name="mode"><option value="standard" ${state.mode==='standard'?'selected':''}>标准 · 需要权衡预算</option><option value="gentle" ${state.mode==='gentle'?'selected':''}>舒缓 · 更宽裕的预算</option></select></label></div><label class="field">人生种子<input name="seed" value="${esc(replay?state.seed:'LIFE-'+Math.random().toString(36).slice(2,8).toUpperCase())}" maxlength="40" required></label><p class="small">同一种子提供相同气质、手牌与事件序列，方便比较不同选择。城市名称提供故事背景，当前共用虚构规则。</p><div class="modal-actions"><button class="button primary" type="submit">开始这段人生</button><button class="button" type="button" data-action="daily">使用今日共同种子</button></div></form>`);}
function exportSave(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='life-meadow-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('存档已导出，包含当前人生进度。');}
function help(){modal('怎么玩，以及它能解释什么',`<h3>三个步骤，走过一年</h3><ol><li>从5张手牌中选1—3张；注意时间和预算。</li><li>不同类型形成组合。确认后结算，再回应一个随机事件。</li><li>每3年选择一件持续生效的信物，18岁得到结局与复盘。</li></ol><h3>数学让选择有代价</h3><p>正向基础收益 ×（1 − 当前属性 ÷ 150），再扣1点年度维持消耗，四舍五入。社区、气质、组合和信物先加入基础收益。负荷超过55时会扣减活力和幸福。事件收益直接结算。留白能恢复，搬家有成本。</p><h3>生物学有启发，不等于医学模型</h3><p>气质、压力积累、恢复和环境共同作用，是本作的灵感。气质标签不等于基因检测结果。所有系数、健康事件频率和成长分数均为游戏设定。</p><p>精神分裂症涉及多个基因及环境因素，不能由单个基因或几次养育选择预测。游戏只设置青少年求助故事，不诊断、不显示编造的个人患病概率，也不把疾病当作失败结局。<a href="https://www.nimh.nih.gov/health/publications/schizophrenia" target="_blank" rel="noopener">NIMH 科普</a></p><h3>经济学的边界</h3><p>邻里研究启发“累计环境暴露”的玩法，但美国研究不能直接转换成中国社区的个人收益预测。这里的社区、收入、住房和教育指数全部虚构；背景指数不直接给孩子加分。<a href="https://www.nber.org/papers/w21156" target="_blank" rel="noopener">Moving to Opportunity 研究</a></p><h3>随时暂停</h3><p>进度仅自动保存在当前浏览器，没有账号同步。可导出、导入存档。无连续签到奖励、付费抽卡或真实交易。读取存档时会校验格式，但本地分数不适合竞技排行榜。</p>`);}
function future(){modal('你会为哪一种人生买单？',`<p>当前试玩的18年、24张活动牌、12件信物和所有结局均免费开放。尚未开放收费。</p><h3>完整版的设计方向</h3><div class="table-wrap"><table><tr><th>想获得什么</th><th>值得付费的内容</th></tr><tr><td>新的故事与情感</td><td>不同家庭关系、时代背景和成人阶段</td></tr><tr><td>更多策略深度</td><td>有独特机制的新社区、职业与信物</td></tr><tr><td>创造与表达</td><td>剧本编辑器、挑战分享、可收藏的人生册</td></tr></table></div><p>计划采用一次购买完整内容、按需购买扩展剧本。价格和内容尚待真实试玩反馈验证，不出售“更好的基因”、疾病豁免或抽卡机会。</p><p class="small">Steam版与微信小游戏版尚未上架。当前为网页试玩，可在手机与电脑继续同一种玩法。</p>`);}
document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el||el.disabled)return;const d=el.dataset;if(d.tab){tab=d.tab;render();return;}if(d.card){act(s=>selectCards(s,s.plan.includes(d.card)?s.plan.filter(id=>id!==d.card):[...s.plan,d.card]));return;}if(d.event!==undefined){act(s=>chooseEvent(s,Number(d.event)));return;}if(d.relic){act(s=>chooseRelic(s,d.relic));return;}if(d.move){act(s=>move(s,d.move));return;}if(d.collection){collection=d.collection;render();return;}switch(d.action){case'resolve':act(resolveYear);break;case'reroll':act(reroll);break;case'new':newDialog();break;case'replay':newDialog(true);break;case'close':$('#modal').close();break;case'help':help();break;case'future':future();break;case'daily':$('#new-form [name=seed]').value='DAY-'+new Date().toISOString().slice(0,10);toast('已填入今日种子，无限次游玩，没有限时奖励。');break;case'save-menu':modal('把这一段人生带走',`<p>当前进度自动保存在这台设备。换浏览器或清除网站数据可能丢失进度，可导出一份备份。</p><p class="small">${esc(state.name)} · ${state.age}岁 · 种子 ${esc(state.seed)}</p><div class="modal-actions"><button class="button primary" data-action="export">导出当前存档</button><button class="button" data-action="import">导入存档并替换当前进度</button></div>`);break;case'export':exportSave();break;case'import':$('#import-file').click();break;case'share':{const end=ending(state),text=`我在《人生原野》陪${state.name}走过了18年，结局是「${end.name}」。发现${state.combos.length}种成长组合。人生种子：${state.seed}。同样的起点，你会怎么选？`;try{await navigator.clipboard.writeText(text);toast('人生摘要已复制。');}catch{modal('分享这段人生',`<p>${esc(text)}</p><p class="small">长按文字即可复制。</p>`);}break;}}});
document.addEventListener('submit',e=>{if(e.target.id!=='new-form')return;e.preventDefault();const f=new FormData(e.target);state=newGame({name:f.get('child'),city:f.get('city'),seed:f.get('seed'),mode:f.get('mode')});tab='board';save();$('#modal').close();render();toast('新的人生已经开始。');});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>500000)throw Error('存档文件过大。');const imported=validateSave(JSON.parse(await f.text()));state=imported;tab='board';save();$('#modal').close();render();toast('已恢复存档。');}catch(err){toast('无法导入：'+err.message);}e.target.value='';});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
save();render();
// Optional WebMCP: the same read-only state and staged actions as the visible UI.
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_parenting_game',description:'Read the current fictional parenting game state and available cards without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({age:state.age,phase:state.phase,stats:state.stats,cash:state.cash,load:state.load,cards:available(state).map(c=>({id:c.id,name:c.name})),selected:state.plan})});register({name:'stage_growth_cards',description:'Select up to three available activity cards. Does not advance the year.',inputSchema:{type:'object',properties:{cardIds:{type:'array',items:{type:'string'},maxItems:3}},required:['cardIds'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Array.isArray(input.cardIds)||Object.keys(input).some(k=>k!=='cardIds'))throw Error('Expected cardIds only.');state=selectCards(state,input.cardIds);tab='board';save();render();return {selected:state.plan,preview:forecast(state)};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
